GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Multi-start greedy + local search to get an upper bound, then binary
    search on the target max KVPR T with a bin-packing-style feasibility
    check: for each of several model orderings, place every model on the
    tightest-fitting GPU that keeps (load_g + r)/(free_g - size) <= T.
    If any ordering places all models, T is feasible. Bisect 40 iterations,
    re-run feasibility at the best feasible bound, and polish with local
    search (single-model moves + pairwise swaps with sideways budget).
    Always returns a dict mapping gpu_id -> list of models.
    """

    def kvpr(load, free):
        return load / free if free > 0 else float('inf')

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            r = model.req_rate / model.slo
            best_idx, best_ratio = None, float('inf')
            for g in range(gpu_num):
                if free[g] - model.model_size > 0:
                    ratio = kvpr(load[g] + r, free[g] - model.model_size)
                    if ratio < best_ratio:
                        best_ratio, best_idx = ratio, g
            if best_idx is None:
                return None, None, None
            placement[best_idx].append(model)
            load[best_idx] += r
            free[best_idx] -= model.model_size
        return placement, free, load

    def refine(placement, free, load):
        # Local search accepting improving moves plus a budgeted number of
        # sideways (equal max KVPR) moves to escape plateaus.
        sideways_budget = 20
        improved = True
        while improved:
            improved = False
            cur_max = max(kvpr(load[g], free[g]) for g in range(gpu_num))
            # Pass 1: single-model moves
            for src in range(gpu_num):
                for model in list(placement[src]):
                    r = model.req_rate / model.slo
                    for dst in range(gpu_num):
                        if dst == src or free[dst] - model.model_size <= 0:
                            continue
                        new_max = max(
                            kvpr(load[src] - r, free[src] + model.model_size),
                            kvpr(load[dst] + r, free[dst] - model.model_size),
                            max(kvpr(load[g], free[g]) for g in range(gpu_num)
                                if g not in (src, dst)),
                        )
                        if new_max < cur_max - 1e-12 or (
                                new_max <= cur_max + 1e-12
                                and sideways_budget > 0):
                            if new_max >= cur_max - 1e-12:
                                sideways_budget -= 1
                            placement[src].remove(model)
                            placement[dst].append(model)
                            load[src] -= r; free[src] += model.model_size
                            load[dst] += r; free[dst] -= model.model_size
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                continue
            # Pass 2: pairwise swaps
            for src in range(gpu_num):
                for dst in range(src + 1, gpu_num):
                    for m1 in list(placement[src]):
                        for m2 in list(placement[dst]):
                            r1, r2 = m1.req_rate / m1.slo, m2.req_rate / m2.slo
                            fs = free[src] + m1.model_size - m2.model_size
                            fd = free[dst] + m2.model_size - m1.model_size
                            if fs <= 0 or fd <= 0:
                                continue
                            others = max(
                                (kvpr(load[g], free[g]) for g in range(gpu_num)
                                 if g not in (src, dst)), default=0.0)
                            new_max = max(
                                kvpr(load[src] - r1 + r2, fs),
                                kvpr(load[dst] - r2 + r1, fd),
                                others,
                            )
                            if new_max < cur_max - 1e-12:
                                placement[src].remove(m1); placement[src].append(m2)
                                placement[dst].remove(m2); placement[dst].append(m1)
                                load[src] += r2 - r1
                                free[src] = fs
                                load[dst] += r1 - r2
                                free[dst] = fd
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        return placement

    def feasible(T, order):
        # Best-fit bin packing under KVPR bound T.
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            r = model.req_rate / model.slo
            best_idx = None
            best_free = None
            for g in range(gpu_num):
                if free[g] - model.model_size <= 0:
                    continue
                if (load[g] + r) / (free[g] - model.model_size) <= T + 1e-9:
                    if best_free is None or free[g] < best_free:
                        best_free, best_idx = free[g], g
            if best_idx is None:
                return None, None, None
            placement[best_idx].append(model)
            load[best_idx] += r
            free[best_idx] -= model.model_size
        return placement, free, load

    import random
    rng = random.Random(42)
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size,
               reverse=True),
        list(models),
    ]
    for _ in range(3):
        order = list(models)
        rng.shuffle(order)
        orders.append(order)

    # Upper bound from greedy (also our fallback).
    best_placement, best_free, best_load = None, None, None
    best_max = float('inf')
    for order in orders:
        placement, free, load = greedy(order)
        if placement is None:
            continue
        placement = refine(placement, free, load)
        cur_max = max(kvpr(load[g], free[g]) for g in range(gpu_num))
        if cur_max < best_max:
            best_max, best_placement, best_free, best_load = \
                cur_max, placement, free, load

    # Binary search on T using the feasibility check.
    if best_placement is not None:
        lo, hi = 0.0, best_max
        for _ in range(40):
            mid = (lo + hi) / 2.0
            for order in orders:
                placement, free, load = feasible(mid, order)
                if placement is not None:
                    break
            if placement is not None:
                hi = mid
            else:
                lo = mid
        # Re-run feasibility at hi (best feasible bound) to get placement.
        placement = None
        for order in orders:
            placement, free, load = feasible(hi, order)
            if placement is not None:
                break
        if placement is not None:
            placement = refine(placement, free, load)
            cur_max = max(kvpr(load[g], free[g]) for g in range(gpu_num))
            if cur_max < best_max:
                best_max = cur_max
                best_placement = placement

    if best_placement is None:
        # No ordering fit; fall back to a best-effort placement that always
        # returns a dict (overcommit only if truly impossible).
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        for model in sorted(models, key=lambda m: m.model_size):
            fits = [g for g in range(gpu_num) if free[g] >= model.model_size]
            g = fits[0] if fits else min(range(gpu_num),
                                         key=lambda x: free[x])
            placement[g].append(model)
            free[g] -= model.model_size
        best_placement = placement

    return best_placement

# EVOLVE-BLOCK-END


